import{_ as a,o as t,c as r,a2 as n}from"./chunks/framework.DVi-36OM.js";const p=JSON.parse('{"title":"Knowledge bundles (.frc)","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/bundles.md","filePath":"architecture/bundles.md"}'),o={name:"architecture/bundles.md"};function s(l,e,i,d,c,u){return t(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="knowledge-bundles-frc" tabindex="-1">Knowledge bundles (.frc) <a class="header-anchor" href="#knowledge-bundles-frc" aria-label="Permalink to &quot;Knowledge bundles (.frc)&quot;">​</a></h1><p><code>.frc</code> files are checksummed, versioned archives carrying two things:</p><ol><li><strong>Patterns</strong>, vulnerability examples with metadata (observation, impact, CWE, CVSS, OWASP, severity).</li><li><strong>Learned facts</strong>, replay-verified Source / Sink / Sanitizer / Policy / Check facts the engine merges into its fact table at scan time.</li></ol><h2 id="loading-order" tabindex="-1">Loading order <a class="header-anchor" href="#loading-order" aria-label="Permalink to &quot;Loading order&quot;">​</a></h2><p>At scan time the engine loads spec tables, then seed facts, then merges the bundle. A bundle is discovered from (in order):</p><ul><li>the <code>--corpus-bundle</code> / <code>--bundle</code> CLI flag,</li><li>the <code>FRENSENSE_CORPUS_BUNDLE</code> environment variable (MCP / LSP),</li><li>auto-discovery of <code>frensense-corpus.frc</code> in the scanned root.</li></ul><h2 id="why-facts-not-rules" tabindex="-1">Why facts, not rules <a class="header-anchor" href="#why-facts-not-rules" aria-label="Permalink to &quot;Why facts, not rules&quot;">​</a></h2><p>Facts are lower-level than &quot;regex rules&quot;: a learned sink participates in the same graph analysis as a builtin one, so taint paths, guard recognition, and value reasoning all apply to it. The bundler only publishes a fact after it replays against labelled positive <em>and</em> negative examples (support ≥ 2).</p>',8)])])}const f=a(o,[["render",s]]);export{p as __pageData,f as default};
